          tipo: 'codigo', lenguaje: 'python', titulo: 'Grader de código para una llamada a herramienta',
          codigo: `from jsonschema import validate, ValidationError

def puntuar_llamada(llamada, esperado, esquemas):
    """llamada / esperado: {"nombre": str | None, "args": dict}"""
    res = {"herramienta_ok": llamada["nombre"] == esperado["nombre"]}
    if esperado["nombre"] is None:          # lo correcto era NO llamar
        res["args_ok"] = llamada["nombre"] is None
        return res
    try:
        validate(llamada["args"], esquemas[esperado["nombre"]])
        res["esquema_ok"] = True
    except (ValidationError, KeyError):
        res["esquema_ok"] = False
    # solo comparamos los campos que determinan el efecto
    claves = esperado.get("campos_clave", esperado["args"].keys())
    norm = lambda v: str(v).strip().lower()
    res["args_ok"] = res["esquema_ok"] and all(
        norm(llamada["args"].get(k)) == norm(esperado["args"][k]) for k in claves)
    return res`,
